import hashlib
import json


def export_name(patient_id: str, day: str) -> str:
    """Cache file name for a daily export."""
    return hashlib.md5(f"{patient_id}:{day}".encode()).hexdigest() + ".json"


def integrity(record: dict) -> str:
    body = json.dumps(record, sort_keys=True).encode()
    return hashlib.sha256(body).hexdigest()

