import hashlib

from clinic.records import integrity


def dedupe_key(content: bytes) -> str:
    return hashlib.sha1(content).hexdigest()


def receipt(content: bytes, meta: dict) -> dict:
    return {"key": dedupe_key(content), "integrity": integrity(meta)}

