import hashlib
import hmac
import secrets

SESSION_KEY = secrets.token_bytes(32)


def sign(session_id: str) -> str:
    return hmac.new(SESSION_KEY, session_id.encode(), hashlib.sha1).hexdigest()


def check(session_id: str, tag: str) -> bool:
    return hmac.compare_digest(sign(session_id), tag)

