import ssl
import urllib.request

from clinic.uploads import receipt


def lab_context() -> ssl.SSLContext:
    context = ssl.create_default_context()
    context.minimum_version = ssl.TLSVersion.TLSv1_2
    return context


def send(url: str, content: bytes) -> dict:
    with urllib.request.urlopen(url, data=content, context=lab_context()) as response:
        return receipt(content, {"status": response.status})
